	private static bool $printed = false;

	/** True when an icon with this name exists. */
	public static function has( string $name ): bool {
		return isset( self::ICONS[ $name ] );
	}

	/**
	 * The icon as an inline <svg>, 1em square, in the current text color.
	 * Decorative (aria-hidden): the text next to it says what it means.
	 * Works anywhere, including outside the plugin's own screens.
	 */
	public static function svg( string $name, string $class = '' ): string {
		if ( ! isset( self::ICONS[ $name ] ) ) return '';
		$cls = trim( 'wpwaf-ic wpwaf-ic-' . $name . ' ' . $class );
		return '<svg class="' . esc_attr( $cls ) . '" width="1em" height="1em" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false" style="vertical-align:-0.125em;flex-shrink:0">'
			. self::ICONS[ $name ] . '</svg>';
	}

	/**
	 * Silhouette of a Quick Pick region on a transparent background, in the
	 * highlight color (styled by .wpwaf-rg-area). 15px tall; the width follows
	 * the region's shape.
	 */
	public static function region( string $region ): string {
		if ( ! isset( self::REGION_MAPS[ $region ] ) ) return '';
		$m  = self::REGION_MAPS[ $region ];
		$id = 'wpwaf-rg-' . $region;
		$w  = round( 15 * $m['w'] / $m['h'], 1 );
		return '<svg class="wpwaf-rg" width="' . $w . '" height="15" viewBox="0 0 ' . (int) $m['w'] . ' ' . (int) $m['h'] . '" aria-hidden="true" focusable="false">'
			. '<defs><clipPath id="' . esc_attr( $id ) . '"><path d="' . esc_attr( $m['area'] ) . '"/></clipPath></defs>'
			. '<path class="wpwaf-rg-area" d="' . esc_attr( $m['land'] ) . '" fill="#FF6A00" fill-rule="evenodd" clip-path="url(#' . esc_attr( $id ) . ')"/>'
			. '</svg>';
	}

	/** Icon, a space and escaped text. */
	public static function text( string $name, string $text ): string {
		return self::svg( $name ) . ' ' . esc_html( $text );
	}

	/**
	 * Prints the JavaScript helpers once, in the <head> of the plugin's screens,
	 * so every inline page script can use them.
	 */
	public static function print_script(): void {
		if ( self::$printed ) return;
		self::$printed = true;
		$icons = wp_json_encode( self::ICONS );
		?>
<script id="wpwaf-icons">
(function(){
	var I = <?php echo $icons; // JSON from wp_json_encode. ?>;
	function esc(s){ return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
	/* Inline SVG markup for an icon name ('' when unknown). */
	window.wpwafIcon = function(name, cls){
		if (!I[name]) return '';
		return '<svg class="wpwaf-ic wpwaf-ic-' + name + (cls ? ' ' + cls : '') + '" width="1em" height="1em" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false" style="vertical-align:-0.125em;flex-shrink:0">' + I[name] + '</svg>';
	};
	/* Icon, a space and escaped text, as HTML. */
	window.wpwafIconText = function(name, text){
		var ic = window.wpwafIcon(name);
		return (ic ? ic + ' ' : '') + esc(text);
	};
	/* Sets an element to an icon plus plain text (the text is escaped). */
	window.wpwafSetText = function(el, name, text){
		if (el) el.innerHTML = window.wpwafIconText(name, text);
	};
	/* Toast body: a check for success, an X for errors, or the icon given. */
	window.wpwafToastBody = function(msg, ok, icon){
		return window.wpwafIconText(icon || (ok === false ? 'x' : 'check'), msg);
	};
	window.wpwafEsc = esc;
})();
</script>
		<?php
	}
